import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const l="/img/math-sum-multiple-adv.svg",g=JSON.parse('{"title":"小学奥数进阶：和倍问题实战技巧","description":"和倍问题是应用题中的核心模型。通过寻找“1 份量”，我们可以轻松化解复杂的数量关系。本文详解和倍问题的各种变式。","frontmatter":{"title":"小学奥数进阶：和倍问题实战技巧","date":"2026-02-08T09:10:00.000Z","categories":["数学"],"tags":["小学数学","奥数","和倍问题"],"description":"和倍问题是应用题中的核心模型。通过寻找“1 份量”，我们可以轻松化解复杂的数量关系。本文详解和倍问题的各种变式。","cover":"/img/math-sum-multiple-adv.svg","top_img":"/img/math-sum-multiple-adv.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-sum-multiple-adv.md","filePath":"posts/primary-math-olympiad-sum-multiple-adv.md","lastUpdated":null}'),p={name:"posts/primary-math-olympiad-sum-multiple-adv.md"};function r(o,a,e,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数进阶-和倍问题实战技巧" tabindex="-1">小学奥数进阶：和倍问题实战技巧 <a class="header-anchor" href="#小学奥数进阶-和倍问题实战技巧" aria-label="Permalink to &quot;小学奥数进阶：和倍问题实战技巧&quot;">​</a></h1><h2 id="一、-核心模型回顾" tabindex="-1">一、 核心模型回顾 <a class="header-anchor" href="#一、-核心模型回顾" aria-label="Permalink to &quot;一、 核心模型回顾&quot;">​</a></h2><p>已知两个数的<strong>和</strong>以及它们的<strong>倍数关系</strong>，求这两个数。</p><ul><li><strong>小数（1份量）= 和 ÷ (倍数 + 1)</strong></li><li><strong>大数 = 小数 × 倍数</strong></li></ul><h3 id="图解逻辑" tabindex="-1">图解逻辑 <a class="header-anchor" href="#图解逻辑" aria-label="Permalink to &quot;图解逻辑&quot;">​</a></h3><p><img src="'+l+'" alt="和倍问题进阶图解"></p><p>将较小的数看作“1 份”，较大的数就是“n 份”。总和对应的就是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>n</mi><mo>+</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(n + 1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">n</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span> 份。</p><hr><h2 id="二、-进阶变式-不标准的倍数" tabindex="-1">二、 进阶变式：不标准的倍数 <a class="header-anchor" href="#二、-进阶变式-不标准的倍数" aria-label="Permalink to &quot;二、 进阶变式：不标准的倍数&quot;">​</a></h2><p>在复杂的奥数题中，倍数关系往往不是整倍数，或者存在“多一点”或“少一点”的情况。</p><h3 id="_1-多几-或-少几-的和倍问题" tabindex="-1">1. “多几”或“少几”的和倍问题 <a class="header-anchor" href="#_1-多几-或-少几-的和倍问题" aria-label="Permalink to &quot;1. “多几”或“少几”的和倍问题&quot;">​</a></h3><p><strong>例题</strong>：甲乙两数之和是 52。甲数比乙数的 3 倍多 4。求甲乙两数各是多少？</p><p><strong>解析</strong>：</p><ul><li><strong>画图思维</strong>： <ul><li>乙是 1 份。</li><li>甲是 3 份还多 4。</li><li>那么甲 + 乙 = 1 份 + (3 份 + 4) = 4 份 + 4。</li></ul></li><li><strong>转化</strong>： <ul><li>总和 52 包含了 4 份和多出来的 4。</li><li>如果我们把这多出来的 4 减掉，剩下的就是整整 4 份了。</li><li><strong>4 份对应的和</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>2</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>4</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">52 - 4 = 48</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span></span></span></span>。</li></ul></li><li><strong>计算</strong>： <ul><li><strong>乙（1份量）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>8</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">48 \\div 4 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>。</li><li><strong>甲</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>×</mo><mn>3</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">12 \\times 3 + 4 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>。</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>5</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">40 + 12 = 52</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">2</span></span></span></span>；40 \\div 12 = 3 \\dots 4，正确！</li></ul><h3 id="_2-三个数的和倍关系" tabindex="-1">2. 三个数的和倍关系 <a class="header-anchor" href="#_2-三个数的和倍关系" aria-label="Permalink to &quot;2. 三个数的和倍关系&quot;">​</a></h3><p><strong>例题</strong>：甲乙丙三数之和是 100。甲是乙的 2 倍，丙是乙的 3 倍还多 4。求三数各是多少？</p><p><strong>解析</strong>：</p><ul><li><strong>以乙为基准（1份）</strong>： <ul><li>乙 = 1 份。</li><li>甲 = 2 份。</li><li>丙 = 3 份 + 4。</li></ul></li><li><strong>求总份数</strong>： <ul><li>总和 = 1份 + 2份 + (3份 + 4) = 6份 + 4。</li></ul></li><li><strong>计算</strong>： <ul><li>6份 + 4 = 100 \\rightarrow 6份 = 96 \\rightarrow 1份 = 16。</li><li>乙 = 16。</li><li>甲 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">16 \\times 2 = 32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span>。</li><li>丙 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mo>×</mo><mn>3</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>5</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">16 \\times 3 + 4 = 52</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">2</span></span></span></span>。</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mo>+</mo><mn>3</mn><mn>2</mn><mo>+</mo><mn>5</mn><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">16 + 32 + 52 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>，正确！</li></ul><hr><h2 id="三、-解题金钥匙" tabindex="-1">三、 解题金钥匙 <a class="header-anchor" href="#三、-解题金钥匙" aria-label="Permalink to &quot;三、 解题金钥匙&quot;">​</a></h2><ol><li><strong>找准“1 份量”</strong>：通常选题目中最小的数或者作为比较基准的数为 1 份。</li><li><strong>“去多补少”</strong>： <ul><li>如果是“多几”，就从总和里<strong>减去</strong>。</li><li>如果是“少几”，就往总和里<strong>加上</strong>。</li></ul></li><li><strong>对应求解</strong>：用调整后的总和除以总份数，得到 1 份量。</li></ol><hr><h2 id="四、-举一反三-练习题" tabindex="-1">四、 举一反三（练习题） <a class="header-anchor" href="#四、-举一反三-练习题" aria-label="Permalink to &quot;四、 举一反三（练习题）&quot;">​</a></h2><ol><li>某学校买来足球和篮球共 54 个，足球的个数比篮球的 2 倍少 6 个。足球和篮球各有多少个？</li><li>三个小组共植树 60 棵。第一小组植树的棵数是第二小组的 2 倍，第三小组比第一小组多植 5 棵。三个小组各植树多少棵？</li></ol><hr><p><em>记住：先调整总和，再求一份量！</em></p>',26)])])}const u=s(p,[["render",r]]);export{g as __pageData,u as default};
